SELECT T2.DISPLAYNAME, T2.WEBSITEURL FROM VOTES AS T1 JOIN USERS AS T2 ON T1.USERID = T2.ID WHERE T1.VOTETYPEID = 8 ORDER BY T1.BOUNTYAMOUNT DESC LIMIT 1;
