SELECT T1.URL FROM CONSTRUCTORS AS T1 JOIN CONSTRUCTORSTANDINGS AS T2 ON T1.CONSTRUCTORID = T2.CONSTRUCTORID GROUP BY T1.CONSTRUCTORID ORDER BY SUM(T2.WINS) DESC LIMIT 1;
